/**
 * Ansh's sprites: the office owner as a properly proportioned human, so he
 * stands apart from the chibi crowd. The sheet (ansh-sheet.json, generated by
 * scripts/generate-ansh-sprites.mjs in the chibi sheets' 112×96 format) is in
 * the same palette-keyed shape as the Clawd sheet, so it decodes the same way.
 */

import sheetData from './ansh-sheet.json';
import { decodeClawdSheet } from './clawdSprites.js';
import type { CharacterSprites } from './spriteData.js';
import { buildCharacterSprites } from './spriteData.js';

let cached: CharacterSprites | null = null;

export function getAnshSprites(): CharacterSprites {
  cached ??= buildCharacterSprites(decodeClawdSheet(sheetData));
  return cached;
}
